UPDATE t_comment_inbox
SET status = 'APPLIED', applied_time = #{appliedTime}, lease_owner = NULL, lease_until = NULL,
    last_error = NULL, updated_time = #{appliedTime}
WHERE id = #{id} AND status = 'PROCESSING' AND lease_owner = #{owner} AND lease_version = #{leaseVersion}

UPDATE t_comment_inbox
SET status = 'PENDING', next_attempt_at = #{nextAttemptAt}, last_error = #{lastError},
    lease_owner = NULL, lease_until = NULL, updated_time = #{updatedTime}
WHERE id = #{id} AND status = 'PROCESSING' AND lease_owner = #{owner} AND lease_version = #{leaseVersion}
